     1	/**
     2	 * Builds the daily digest bundle per recipient from unread notifications inside the org's digest window.
     3	 *
     4	 * Must call (do not reimplement): isEnabled, renderEmail
     5	 */
     6	import { isEnabled } from "@/lib/feature-flags";
     7	import { DIGEST_MAX_ENTRIES } from "@/config/constants";
     8	import * as notificationRepo from "@/server/repositories/notification-repository";
     9	import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
    10	import * as orgRepo from "@/server/repositories/organization-repository";
    11	import { renderEmail } from "./email-service";
    12	import { buildFlagContext } from "./feature-flag-service";
    13	import type { RenderedEmail } from "@/server/services/email-service";
    14	import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
    15	import type { User } from "@/types/member";
    16	import type { DigestBundle, DigestEntry } from "@/types/notification";
    17	
    18	/** A digest with fewer entries than this is not worth an email. */
    19	const MIN_ENTRIES = 1;
    20	
    21	/**
    22	 * Collects one recipient's unread notifications inside the window. Returns
    23	 * `null` — rather than an empty bundle — when the org's plan does not include
    24	 * the digest, or when there is nothing to say: the caller treats `null` as
    25	 * "send nothing", so a quiet day produces no mail at all.
    26	 */
    27	export async function buildDigest(
    28	  orgId: OrgId,
    29	  recipientId: UserId,
    30	  windowStart: IsoTimestamp,
    31	  windowEnd: IsoTimestamp,
    32	): Promise<DigestBundle | null> {
    33	  const org = await orgRepo.findOrgById(orgId);
    34	  if (!org) return null;
    35	
    36	  if (!isEnabled("digest_email", buildFlagContext(null, org))) return null;
    37	
    38	  const unread = await notificationRepo.listUnreadSince(
    39	    orgId,
    40	    recipientId,
    41	    windowStart,
    42	  );
    43	
    44	  const entries: DigestEntry[] = unread
    45	    .filter((notification) => notification.createdAt <= windowEnd)
    46	    .map((notification) => ({
    47	      notificationId: notification.id,
    48	      kind: notification.kind,
    49	      title: notification.title,
    50	      href: notification.href,
    51	      occurredAt: notification.createdAt,
    52	    }))
    53	    .slice(0, DIGEST_MAX_ENTRIES);
    54	
    55	  if (entries.length < MIN_ENTRIES) return null;
    56	
    57	  return { orgId, recipientId, entries, windowStart, windowEnd };
    58	}
    59	
    60	/**
    61	 * Who gets a digest: everyone who set at least one notification kind to
    62	 * `digestOnly`. Opting into the digest is what suppresses the immediate
    63	 * emails, so the two lists are two views of the same preference.
    64	 */
    65	export async function listDigestRecipients(
    66	  orgId: OrgId,
    67	): Promise<readonly UserId[]> {
    68	  return preferenceRepo.listDigestSubscribers(orgId);
    69	}
    70	
    71	/** Renders one bundle through the shared email pipeline. */
    72	export async function renderDigest(
    73	  bundle: DigestBundle,
    74	  recipient: User,
    75	): Promise<RenderedEmail> {
    76	  return renderEmail("digest", {
    77	    orgId: bundle.orgId,
    78	    recipientName: recipient.name,
    79	    entryCount: bundle.entries.length,
    80	    windowStart: bundle.windowStart,
    81	    windowEnd: bundle.windowEnd,
    82	    headline: bundle.entries[0]?.title ?? "",
    83	  });
    84	}
