    16	export async function POST(request: Request): Promise<Response> {
    17	  try {
    18	    assertCronSecret(request);
    19	
    20	    const result = await runDigestEmailJob(new Date());
    21	    return Response.json(result);
    22	  } catch (error) {
    23	    return errorResponse(error);
    24	  }
